<template>
  <MobileShell :screen="screen" :scroll-target="scrollTarget" @reach-bottom="onReachBottom">
    <template v-if="screen==='home'">
      <view class="hero">
        <view class="hero-copy"><text class="eyebrow light">让每一份善意，都有回响</text><text class="hero-title">发现需要帮助的它，\n也找到愿意接住它的人</text><text class="hero-sub">每一次救助，都是改变命运的开始。</text><button class="btn primary hero-btn" @click="requireLogin('clue')"><Icon name="send" :size="20" /><text>发布救助线索</text></button></view>
        <view class="hero-visual"><image class="hero-image" src="/static/assets/content/home-hero.jpg" mode="aspectFill" /><text class="hero-credit">用户提供 · 场景示意</text></view>
      </view>
      <view class="home-shortcuts"><button class="btn primary" @click="browseAnimals"><Icon name="heart" :size="24"/>我要领养</button><button class="btn" @click="requireLogin('clue')"><Icon name="pin" :size="24"/>发布线索</button><button v-if="isRescuer" class="btn" @click="goto('tasks')"><Icon name="tasks" :size="24"/>救助任务</button></view><view class="demo-disclosure"><text>演示内容说明</text><text>{{demoNotice}}</text></view><view id="adopt-list" class="title">等待一个家的它们</view>
      <view class="filter-bar">
        <picker :range="speciesOptions.map(x=>x?displayText(x):'全部')" @change="species=speciesOptions[$event.detail.value];reloadHome()"><view class="filter-item">物种：{{species?displayText(species):'全部'}}</view></picker>
        <picker :range="sexOptions.map(x=>x?displayText(x):'全部')" @change="sex=sexOptions[$event.detail.value];reloadHome()"><view class="filter-item">性别：{{sex?displayText(sex):'全部'}}</view></picker>
      </view>
      <PageState :loading="home.loading.value" :error="home.error.value" :empty="!home.records.value.length" :has-data="!!home.records.value.length" :loading-more="home.loadingMore.value" :has-more="home.hasMore.value" empty-text="暂无符合条件的可领养动物" @retry="home.retry">
        <view v-for="a in home.records.value" :key="a.id" class="card archive">
          <AuthImage class="thumb" :src="a.coverImageUrl" fallback="/static/assets/pudding-cat-hero.png" mode="aspectFill"/>
          <view class="grow"><text class="card-title">{{a.name}}</text><text class="muted">{{displayText(a.species)}} · {{displayText(a.sex)}} · {{age(a.estimatedAgeMonths)}}</text><view class="health"><Icon name="heart" :size="18" /><text>{{a.healthCondition}}</text></view><view class="actions"><button class="btn" @click="goto('animal',{id:a.id})"><Icon name="eye" :size="18" /><text>查看档案</text></button><button v-if="logged" class="btn primary" :disabled="favoriteBusy===a.id" @click="favorite(a)"><Icon name="heart" :size="18" />{{favoriteBusy===a.id?'处理中…':'收藏'}}</button></view></view>
        </view>
      </PageState>
      <view class="story-block">
        <view class="story-heading"><view><text class="eyebrow">救助纪实 · RESCUE LOG</text><text class="title">不止看见结果，也看见过程</text></view><text class="muted">每一步都有记录</text></view>
        <view v-for="story in rescueStories.slice(0,1)" :key="story.slug" class="rescue-story">
          <view class="rescue-cover"><view class="rescue-gallery"><view v-for="photo in story.images" :key="photo.src"><AuthImage :src="mobileAsset(photo.src)" :fallback="mobileAsset(story.fallback)" :alt="story.name+photo.label" mode="aspectFill"/><text>{{photo.label}}</text></view></view><text class="rescue-status">{{story.status}}</text><small @click="openSource(story.sourceUrl)">图片来源：{{story.credit}} ↗</small></view>
          <view class="rescue-body"><view class="story-meta"><text>{{story.area}}</text><text>{{story.profile}}</text></view><text class="story-name">{{story.name}}</text><text class="story-summary">{{story.summary}}</text><view class="mobile-timeline"><view v-for="item in story.milestones" :key="item.time+item.title"><text class="timeline-time">{{item.time}}</text><view><text class="timeline-title">{{item.title}}</text><text class="muted">{{item.text}}</text></view></view></view><text class="care-note">{{story.note}}</text></view>
        </view>
      </view>
      <view class="letters-block"><text class="eyebrow">新家来信 · FOLLOW-UP</text><text class="title">领养之后，故事还在继续</text><scroll-view class="letter-scroll" scroll-x :show-scrollbar="false"><view class="letter-row"><view v-for="letter in familyLetters" :key="letter.name" class="family-letter"><AuthImage :src="mobileAsset(letter.image)" :fallback="mobileAsset(letter.fallback)" :alt="letter.name" mode="aspectFill"/><view><text class="letter-period">{{letter.period}}</text><text class="card-title">{{letter.name}}</text><text class="letter-quote">“{{letter.quote}}”</text><text class="muted">{{letter.detail}}</text><text class="image-credit source-link" @click="openSource(letter.sourceUrl)">图片来源：{{letter.credit}} ↗</text></view></view></view></scroll-view></view>
      <view class="trust-strip"><view v-for="item in trustPractices" :key="item.number"><text>{{item.number}}</text><view><text class="card-title">{{item.title}}</text><text class="muted">{{item.text}}</text></view></view></view>
      <view class="card"><view class="title">最新公告</view><text v-if="noticeError" class="muted">{{noticeError}}</text><view v-for="n in homeNotices" :key="n.id" class="home-notice" @click="goto('announcementDetail',{id:n.id})"><text class="card-title">{{n.title}}</text><text class="muted">阅读全文 →</text></view><button class="btn wide" @click="goto('announcements')">查看全部公告</button></view><view class="guide"><text class="eyebrow">参与指南</text><text class="card-title">第一次参与救助？</text><text class="muted">安全接近、现场记录、及时求助，一步步陪你完成。</text><button class="btn" @click="guideOpen=!guideOpen">{{guideOpen?'收起指南':'查看参与步骤'}}</button><view v-if="guideOpen" class="guide-steps"><text>1. 先确保自身安全，不追赶或强行接触动物。</text><text>2. 拍摄现场照片，记录准确地点与发现时间，提交救助线索。</text><text>3. 工作人员审核后由救助人员接取，可在“线索”页关注进展。</text><text>4. 领养前了解动物健康及照护需求，获批领养后通过回访分享近况。</text></view></view>
    </template>

    <template v-else-if="screen==='animal'">
      <BackButton/>
      <PageState :loading="detailState.loading.value" :error="detailState.error.value" :empty="!animal" :has-data="!!animal" @retry="loadAnimal">
        <view v-if="animal" class="detail-hero"><AuthImage :src="animal.images?.[0]?.url||animal.coverImageUrl" fallback="/static/assets/pudding-cat-hero.png" mode="aspectFill"/><view class="stamp">{{displayText(animal.status)}}</view></view>
        <scroll-view v-if="animal?.images?.length>1" class="detail-gallery-scroll" scroll-x :show-scrollbar="false"><view class="detail-gallery"><AuthImage v-for="image in animal.images" :key="image.id" :src="image.url" :alt="animal.name+'档案照片'" mode="aspectFill"/></view></scroll-view>
        <view v-if="animal" class="card"><text class="card-title big">{{animal.name}}</text><text class="muted">{{displayText(animal.species)}} · {{displayText(animal.sex)}} · {{age(animal.estimatedAgeMonths)}}</text><view class="health"><Icon name="heart" :size="18" /><text>{{animal.healthCondition}}</text></view><view class="kv"><b>毛色</b><text>{{animal.color||'—'}}</text></view><view class="profile-note"><b>性格观察</b><text>{{animal.personality||'救助人员正在持续观察，后续会补充。'}}</text></view><view class="profile-note"><b>领养要求</b><text>{{animal.adoptionRequirements||'请根据工作人员评估与领养协议完成匹配。'}}</text></view><view class="kv"><b>状态</b><StatusBadge :value="animal.status"/></view><view class="actions"><button v-if="logged" class="btn" @click="favorite(animal)"><Icon name="heart" :size="18" />收藏</button><button v-if="animal.status==='AVAILABLE'" class="btn primary" @click="requireLogin('apply',{animalId:animal.id})"><Icon name="send" :size="18" />申请领养</button></view></view>
        <view class="card"><text class="title">健康记录</text><view v-if="!health.length" class="subtle">暂无公开健康记录</view><view v-for="h in health" :key="h.id" class="timeline"><text>{{h.content}}</text><text class="muted">{{h.createdAt}}</text></view></view>
      </PageState>
    </template>

    <template v-else-if="screen==='responsibleAnimals'">
      <BackButton/><view class="title">我负责的动物</view>
      <PageState :loading="responsible.loading.value" :error="responsible.error.value" :empty="!responsible.records.value.length" :has-data="!!responsible.records.value.length" :loading-more="responsible.loadingMore.value" :has-more="responsible.hasMore.value" @retry="responsible.retry">
        <view v-for="a in responsible.records.value" :key="a.id" class="card archive"><AuthImage class="thumb" :src="a.coverImageUrl" fallback="/static/assets/pudding-cat-hero.png" mode="aspectFill"/><view class="grow"><text class="card-title">{{a.name}}</text><text class="muted">来源任务 #{{a.rescueTaskId||'—'}}</text><StatusBadge :value="a.status"/><view class="actions"><button class="btn" @click="goto('animalManage',{id:a.id})">管理档案</button><button class="btn" @click="goto('adoptionOverview',{id:a.id})">领养情况</button></view></view></view>
      </PageState>
    </template>

    <template v-else-if="screen==='animalManage'">
      <BackButton/>
      <PageState :loading="detailState.loading.value" :error="detailState.error.value" :empty="!animal" :has-data="!!animal" @retry="loadAnimalManage">
        <view v-if="animal" class="title">动物档案管理 · {{animal.name}} #{{animal.id}}</view>
        <view v-if="animal" class="card">
          <FormField label="名称" :error="animalErrors.name"><input v-model="animalEdit.name" class="input"/></FormField>
          <FormField label="种类" :error="animalErrors.species"><input v-model="animalEdit.species" class="input"/></FormField>
          <picker :range="['公','母','未知']" @change="animalEdit.sex=['MALE','FEMALE','UNKNOWN'][$event.detail.value]"><view class="input">{{displayText(animalEdit.sex)}}</view></picker>
          <input v-model.number="animalEdit.estimatedAgeMonths" class="input" type="number" placeholder="估算年龄（月）"/>
          <input v-model="animalEdit.color" class="input" placeholder="毛色"/>
          <FormField label="健康摘要" :error="animalErrors.healthCondition"><textarea v-model="animalEdit.healthCondition" class="input area"/></FormField>
          <FormField label="性格与行为观察"><textarea v-model="animalEdit.personality" class="input area" maxlength="1000" placeholder="陌生人适应、互动偏好、与其他动物相处情况"/></FormField>
          <FormField label="领养家庭要求"><textarea v-model="animalEdit.adoptionRequirements" class="input area" maxlength="1000" placeholder="居住、陪伴、运动、医疗与回访要求"/></FormField>
          <button class="btn primary wide" :disabled="manageSubmit.submitting.value" @click="saveAnimal">{{manageSubmit.submitting.value?'保存中…':'保存基本资料'}}</button>
        </view>
        <view class="card"><text class="title">动物图片</text><ImagePicker v-model="animalTokens"/><button class="btn" :disabled="!animalTokens.length||imageSubmit.submitting.value" @click="addAnimalImages"><Icon name="plus" :size="18" />{{imageSubmit.submitting.value?'处理中…':'追加图片'}}</button><view class="photo-grid"><view v-for="im in animal?.images||[]" :key="im.id" class="photo"><AuthImage class="photo-img" :src="im.url" mode="aspectFill"/><button class="mini danger" :disabled="imageSubmit.submitting.value" aria-label="删除图片" @click="deleteAnimalImage(im)"><Icon name="trash" :size="18" /></button></view></view></view>
        <view class="card"><text class="title">健康记录</text><view v-for="h in health" :key="h.id" class="timeline">{{h.content}}<text class="muted">{{h.createdAt}}</text></view><textarea v-model="healthText" class="input area" placeholder="追加健康记录，最多 2000 字"/><text v-if="healthError" class="inline-error">{{healthError}}</text><button class="btn" :disabled="healthSubmit.submitting.value" @click="addHealth">{{healthSubmit.submitting.value?'提交中…':'追加健康记录'}}</button></view>
        <view v-if="animal" class="card"><text class="title">状态操作</text><view class="notice">领养申请获批后，系统会自动更新领养状态。</view><button v-if="animal.status==='TREATING'" class="btn" :disabled="stateSubmit.submitting.value" @click="animalState('TO_OBSERVING')">进入观察</button><button v-if="animal.status==='OBSERVING'" class="btn primary" :disabled="stateSubmit.submitting.value" @click="animalState('OPEN_ADOPTION')">开放领养</button><button v-if="animal.status==='AVAILABLE'" class="btn danger" :disabled="stateSubmit.submitting.value" @click="suspendAnimal">暂停领养</button><button v-if="animal.status==='SUSPENDED'" class="btn primary" :disabled="stateSubmit.submitting.value" @click="animalState('RESUME_ADOPTION')">恢复领养</button></view>
      </PageState>
    </template>
  </MobileShell>
</template>
<style scoped>
.profile-note{display:flex;flex-direction:column;gap:10rpx;margin-top:24rpx;padding:22rpx;border-left:6rpx solid #cf784c;background:#f4f1e8;line-height:1.75}
.profile-note b{color:#24483f}
.profile-note text{color:#5a6e65}
</style>
<script setup>
import {ref,reactive,onMounted,computed,nextTick} from 'vue'
import {useAuth} from '../../store/auth.js'
import MobileShell from '../../components/MobileShell.vue';import PageState from '../../components/PageState.vue';import AuthImage from '../../components/AuthImage.vue';import BackButton from '../../components/BackButton.vue';import StatusBadge from '../../components/StatusBadge.vue';import FormField from '../../components/FormField.vue';import ImagePicker from '../../components/ImagePicker.vue';import Icon from '../../components/Icon.vue'
import {animalApi,contentApi} from '../../api/index.js';import {useNavigation} from '../../composables/navigation.js';import {usePagedList} from '../../composables/pagedList.js';import {useAsyncState,useSubmit} from '../../composables/asyncState.js';import {currentPageParams} from '../../composables/routeParams.js';import {textRule} from '../../composables/validation.js';import {displayText} from '../../utils/displayText.js'
import {demoNotice,familyLetters,rescueStories,trustPractices} from '../../content/publicContent.js'
const homeNotices=ref([]),noticeError=ref(''),guideOpen=ref(false),scrollTarget=ref('');const isRescuer=computed(()=>useAuth().state.user?.roleCode==='RESCUER')
async function browseAnimals(){scrollTarget.value='';await nextTick();scrollTarget.value='adopt-list'}
async function loadNotices(){try{homeNotices.value=(await contentApi.announcements({page:1,size:3})).records||[]}catch{noticeError.value='公告暂时无法加载，可进入公告页重试'}}
const props=defineProps({screen:{type:String,required:true}});const screen=props.screen;const params=currentPageParams();const {goto,requireLogin,logged}=useNavigation();const speciesOptions=['','CAT','DOG','OTHER'];const sexOptions=['','MALE','FEMALE','UNKNOWN'];const species=ref(''),sex=ref(''),favoriteBusy=ref(null)
const home=usePagedList(q=>animalApi.list(q),{pageSize:20});const responsible=usePagedList(q=>animalApi.responsible(q),{pageSize:20});const detailState=useAsyncState();const animal=ref(null),health=ref([]);const animalEdit=reactive({name:'',species:'',sex:'UNKNOWN',estimatedAgeMonths:null,color:'',healthCondition:'',personality:'',adoptionRequirements:''});const animalTokens=ref([]),healthText=ref(''),healthError=ref('');const manageSubmit=useSubmit(),imageSubmit=useSubmit(),healthSubmit=useSubmit(),stateSubmit=useSubmit();const animalErrors=reactive({name:'',species:'',healthCondition:''})
function age(m){return m==null?'年龄未知':m<12?`${m}个月`:`${Math.floor(m/12)}岁${m%12?m%12+'个月':''}`}
function mobileAsset(path){return path.replace('/assets/','/static/assets/')}
function openSource(url){
  // #ifdef H5
  window.open(url,'_blank','noopener,noreferrer')
  // #endif
  // #ifndef H5
  uni.setClipboardData({data:url,success:()=>uni.showToast({title:'来源链接已复制',icon:'none'})})
  // #endif
}
async function reloadHome(){await home.refresh({...(species.value?{species:species.value}:{}),...(sex.value?{sex:sex.value}:{})})}
async function loadAnimal(){await detailState.run(async()=>{animal.value=await animalApi.detail(params.id);health.value=await animalApi.health(params.id)})}
async function loadAnimalManage(){await detailState.run(async()=>{animal.value=await animalApi.detail(params.id);Object.assign(animalEdit,animal.value);health.value=await animalApi.health(params.id)})}
async function favorite(a){favoriteBusy.value=a.id;try{await contentApi.favorite(a.id);uni.showToast({title:'已收藏'})}finally{favoriteBusy.value=null}}
function validateAnimal(){animalErrors.name=textRule(animalEdit.name,{label:'名称',max:100});animalErrors.species=textRule(animalEdit.species,{label:'种类',max:50});animalErrors.healthCondition=textRule(animalEdit.healthCondition,{label:'健康摘要',max:1000});return !Object.values(animalErrors).some(Boolean)}
async function saveAnimal(){if(!validateAnimal())return;await manageSubmit.submit(async()=>{animal.value=await animalApi.patch(params.id,{name:animalEdit.name.trim(),species:animalEdit.species.trim(),sex:animalEdit.sex,estimatedAgeMonths:animalEdit.estimatedAgeMonths??null,color:animalEdit.color?.trim()||null,healthCondition:animalEdit.healthCondition.trim(),personality:animalEdit.personality?.trim()||null,adoptionRequirements:animalEdit.adoptionRequirements?.trim()||null,version:animal.value.version});Object.assign(animalEdit,animal.value);uni.showToast({title:'已保存'})})}
async function addAnimalImages(){if(!animalTokens.value.length)return;await imageSubmit.submit(async()=>{animal.value=await animalApi.addImages(params.id,{imageTokens:animalTokens.value});animalTokens.value=[]})}
async function deleteAnimalImage(im){await imageSubmit.submit(async()=>{animal.value=await animalApi.deleteImage(params.id,im.id)})}
async function addHealth(){healthError.value=textRule(healthText.value,{label:'健康记录',max:2000});if(healthError.value)return;await healthSubmit.submit(async()=>{await animalApi.addHealth(params.id,{content:healthText.value.trim()});healthText.value='';health.value=await animalApi.health(params.id)})}
async function animalState(action,extra={}){await stateSubmit.submit(async()=>{await animalApi.status(params.id,{action,version:animal.value.version,...extra});await loadAnimalManage()})}
function suspendAnimal(){uni.showModal({title:'暂停领养',editable:true,placeholderText:'请输入暂停原因',success:r=>{if(r.confirm){const reason=String(r.content||'').trim();if(!reason||reason.length>500){uni.showToast({title:'暂停原因需为 1～500 字',icon:'none'});return}animalState('SUSPEND_ADOPTION',{suspendReason:reason})}}})}
function onReachBottom(){if(screen==='home')home.loadMore();else if(screen==='responsibleAnimals')responsible.loadMore()}
async function initialize(){if(screen==='home'){await Promise.all([reloadHome(),loadNotices()])}else if(screen==='animal')await loadAnimal();else if(screen==='responsibleAnimals')await responsible.refresh();else if(screen==='animalManage')await loadAnimalManage()}
onMounted(()=>{void initialize().catch(()=>{})})
</script>
<style scoped>.home-shortcuts{display:flex;gap:16rpx;margin:26rpx 0 40rpx;flex-wrap:wrap}.home-shortcuts .btn{flex:1;min-width:160rpx;display:flex;align-items:center;justify-content:center;gap:12rpx;min-height:94rpx}.hero-credit{position:absolute;right:16rpx;bottom:14rpx;padding:7rpx 10rpx;border-radius:7rpx;background:rgba(18,52,43,.7);color:#fff;font-size:17rpx}.demo-disclosure{display:flex;flex-direction:column;gap:7rpx;margin:0 0 38rpx;padding:22rpx 24rpx;border-left:7rpx solid #cf784c;background:#f3eee2;color:#607168;font-size:21rpx;line-height:1.65}.demo-disclosure text:first-child{color:#8d5e3f;font-weight:700}.story-block,.letters-block{margin:58rpx 0}.story-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:20rpx;margin-bottom:24rpx}.story-heading .title,.letters-block>.title{display:block;margin-top:10rpx}.rescue-story{overflow:hidden;border:1px solid #d8ddce;border-radius:28rpx;background:#f3f0e7}.rescue-cover{position:relative;height:540rpx}.rescue-gallery{display:grid;grid-template-rows:1.2fr .8fr;gap:4rpx;width:100%;height:100%;background:#fff}.rescue-gallery>view{position:relative;min-height:0;overflow:hidden}.rescue-gallery :deep(image){width:100%;height:100%}.rescue-gallery>view>text{position:absolute;right:16rpx;bottom:14rpx;padding:7rpx 10rpx;border-radius:7rpx;background:rgba(18,52,43,.72);color:#fff;font-size:17rpx}.rescue-status{position:absolute;left:24rpx;top:24rpx;padding:12rpx 20rpx;border-radius:999rpx;background:rgba(249,250,244,.92);color:#254b41;font-size:21rpx;font-weight:700}.rescue-cover>small{position:absolute;left:20rpx;bottom:18rpx;padding:7rpx 10rpx;border-radius:6rpx;background:rgba(18,52,43,.8);color:#fff;font-size:17rpx;text-decoration:underline}.rescue-body{padding:32rpx}.story-meta{display:flex;gap:12rpx;flex-wrap:wrap}.story-meta text{padding:9rpx 14rpx;border-radius:8rpx;background:#e0e4d5;color:#536b61;font-size:20rpx}.story-name{display:block;margin:23rpx 0 13rpx;font-family:serif;font-size:56rpx;font-weight:700;color:#183e35}.story-summary{font-size:25rpx;line-height:1.85;color:#51675e}.mobile-timeline{position:relative;margin:32rpx 0}.mobile-timeline::before{content:"";position:absolute;left:83rpx;top:15rpx;bottom:15rpx;width:2rpx;background:#c7cdbb}.mobile-timeline>view{position:relative;display:grid;grid-template-columns:68rpx 1fr;gap:34rpx;margin-bottom:28rpx}.mobile-timeline>view::before{content:"";position:absolute;left:76rpx;top:10rpx;width:14rpx;height:14rpx;border-radius:50%;background:#d07a4d;border:8rpx solid #f3f0e7}.timeline-time{color:#9a6d45;font-size:21rpx;text-align:right}.timeline-title{display:block;margin-bottom:8rpx;font-size:25rpx;font-weight:700;color:#284d43}.mobile-timeline .muted{font-size:22rpx;line-height:1.65}.care-note{display:block;padding:21rpx;border-left:6rpx solid #d07a4d;background:rgba(255,255,255,.65);color:#52685f;font-size:22rpx;line-height:1.65}.letter-scroll{width:100%;margin-top:24rpx}.letter-row{display:flex;gap:22rpx;width:max-content;padding-bottom:12rpx}.family-letter{width:560rpx;overflow:hidden;border:1px solid #d8ddce;border-radius:24rpx;background:#fff;white-space:normal}.family-letter>:deep(image){display:block;width:100%;height:340rpx}.family-letter>view{padding:27rpx}.letter-period{display:block;color:#a16d45;font-size:20rpx;font-weight:700}.family-letter .card-title{display:block;margin:10rpx 0 17rpx}.letter-quote{display:block;color:#36564d;font-family:serif;font-size:26rpx;line-height:1.75}.family-letter .muted{display:block;margin-top:20rpx;padding-top:18rpx;border-top:1px solid #e0e3d8;font-size:21rpx;line-height:1.65}.image-credit{display:block;margin-top:18rpx;color:#8b958f;font-size:18rpx}.source-link{text-decoration:underline}.trust-strip{margin:48rpx 0;padding:18rpx 30rpx;border-radius:28rpx;background:#173f36}.trust-strip>view{display:grid;grid-template-columns:56rpx 1fr;gap:16rpx;padding:25rpx 0;border-bottom:1px solid rgba(255,255,255,.12)}.trust-strip>view:last-child{border:0}.trust-strip>